const input=$json??{};
const decision=String(input.decision??'').toLowerCase();
const strategy=String(input.strategy??'').toLowerCase();
const dealId=input.deal_id??null; const leadId=input.lead_id??null; const propertyId=input.property_id??null;
const dynamicMao=Number(input.dynamic_mao??input.adjusted_mao??input.mao);
const counteroffer=input.counteroffer_amount==null?null:Number(input.counteroffer_amount);
const dnc=Boolean(input.dnc??input.do_not_contact??false); const blockers=Array.isArray(input.blockers)?input.blockers:[];
