const counterValid=counteroffer==null||(Number.isFinite(counteroffer)&&counteroffer>0); const hardBlock=dnc||blockers.length>0;
let outcome='needs_review'; let nextWorkflow='WF-343'; let contractReady=false; let revisedOffer=false; let reengagement=false; let reason='Negotiation outcome requires review.';
if(hardBlock){outcome=dnc?'dnc_blocked':'blocked';nextWorkflow='WF-126';reason=dnc?'Seller is on DNC; no outbound action permitted.':'Active blocker prevents negotiation action.';}
else if(!identityComplete||!maoValid||!counterValid){outcome='incomplete';nextWorkflow='WF-343';reason='Required deal identity, dynamic MAO, or counteroffer data is missing/invalid.';}
else if(decision==='acceptance_ready'){outcome='contract_decision_ready';contractReady=true;nextWorkflow='WF-201';reason='Seller acceptance is ready for human-authorized contract review.';}
else if(decision==='counteroffer_within_mao'){outcome='accept_counteroffer_contract_review';contractReady=true;nextWorkflow='WF-201';reason='Counteroffer is below dynamic MAO and is eligible for controlled contract review.';}
else if(decision==='counteroffer_near_mao'){outcome='revised_offer_or_controlled_accept';revisedOffer=true;nextWorkflow='WF-340';reason='Counteroffer is near dynamic MAO; revised offer or controlled acceptance requires human review.';}
else if(decision==='counteroffer_above_mao'){outcome='above_mao_revised_offer_or_walk_away';revisedOffer=true;nextWorkflow='WF-340';reason='Counteroffer exceeds dynamic MAO; autonomous acceptance is prohibited.';}
else if(decision==='rejection_reengagement'||decision==='no_response'){outcome='reengagement_ready';reengagement=true;nextWorkflow='WF-261';reason='Seller outcome requires controlled re-engagement.';}
else if(decision==='clarification_required'||strategy==='answer_and_negotiate'){outcome='clarification_response_ready';revisedOffer=true;nextWorkflow='WF-340';reason='Seller needs clarification or negotiation response before contract decision.';}
else {outcome='needs_review';nextWorkflow='WF-343';reason='Unsupported WF-344 negotiation decision state.';}
const assetStrategy={residential:'Residential wholesale economics; 70% rule is secondary reference only.',multifamily:'Multifamily economics; prioritize NOI, cap rate/value evidence, debt and buyer demand.',land:'Land economics; prioritize zoning, utilities, access, topography, flood risk, land comps and development potential.',commercial:'Commercial economics; prioritize income/value evidence, lease/tenant factors, financing and exit demand.'}[assetType]??'Asset-specific economics required; 70% rule is secondary reference only.';
const activity={activity_type:'negotiation_decision_revised_offer_contract_decision_controller',subject:'WF-344 '+(dealId??'unknown-deal'),deal_id:dealId,lead_id:leadId,property_id:propertyId,status:outcome,decision,strategy,next_workflow:nextWorkflow,contract_ready:contractReady,revised_offer:revisedOffer,reengagement,counteroffer_amount:counteroffer,dynamic_mao:dynamicMao,asset_type:assetType,asset_strategy:assetStrategy,hard_mao_guardrail:true,human_review_required:true,dnc,blockers,reason};
return [{json:{...input,wf_id:'WF-344',outcome,next_workflow:nextWorkflow,contract_ready:contractReady,revised_offer:revisedOffer,reengagement,counteroffer_amount:counteroffer,dynamic_mao:dynamicMao,asset_type:assetType,asset_strategy:assetStrategy,hard_mao_guardrail:true,human_review_required:true,reason,crm_activity:activity,evaluated_at:new Date().toISOString()}}];
